def test_a_post_without_an_idempotency_key_is_never_repeated(
    server: MockServer,
) -> None:
    path = COMPANY + "/proposals/p_1/reject"
    server.add("POST", path, Reply(status=503, json=error_body("unavailable_error", "Позже.")))
