def test_a_cursor_seen_earlier_stops_the_iteration(sync_client: Tungo, server: MockServer) -> None:
    def respond(request: Recorded) -> Reply:
        cursor = dict(request.query).get("cursor")
        return Reply(json=page_body(["p"], {None: "cursor-a", "cursor-a": "cursor-b", "cursor-b": "cursor-a"}[cursor]))

    server.respond("GET", COMPANY + "/proposals", respond)
    page = sync_client.proposals.list("co_1")
    with pytest.raises(tungoai.PaginationError, match="cursor-a"):
        for _ in page:
            assert len(server.requests) <= 3
    assert len(server.requests) == 3, "A, B, then A again: the loop is noticed without a fourth request"


def test_pages_one_by_one_notice_a_cursor_seen_earlier(sync_client: Tungo, server: MockServer) -> None:
    def respond(request: Recorded) -> Reply:
        cursor = dict(request.query).get("cursor")
        return Reply(json=page_body(["p"], {None: "cursor-a", "cursor-a": "cursor-b", "cursor-b": "cursor-a"}[cursor]))

    server.respond("GET", COMPANY + "/proposals", respond)
    page = sync_client.proposals.list("co_1")
