def test_wait_for_run_gives_up_after_the_timeout(sync_client: Tungo, server: MockServer) -> None:
    server.add("GET", COMPANY + "/automations/runs/run_1", Reply(json=run_body("running")))
    started = time.monotonic()
    with pytest.raises(tungoai.WaitTimeoutError, match="run_1") as caught:
        sync_client.wait_for_run("co_1", "run_1", timeout=0.3, poll_interval=0.05)
    assert isinstance(caught.value, TimeoutError)
    assert 0.25 <= time.monotonic() - started < 3
    with pytest.raises(tungoai.ConfigError):
        sync_client.wait_for_run("co_1", "run_1", timeout=0)


def test_the_wait_helpers_wait_ten_minutes_by_default() -> None:
    for helper in (Tungo.wait_for_run, Tungo.wait_for_batch, Tungo.run_scenario_and_wait):
        assert inspect.signature(helper).parameters["timeout"].default == 600.0


def test_a_run_without_a_state_is_a_decode_error(sync_client: Tungo, server: MockServer) -> None:
    body = {key: value for key, value in run_body("done").items() if key != "state"}
    server.add("GET", COMPANY + "/automations/runs/run_1", Reply(json=body))
    with pytest.raises(tungoai.DecodeError, match="state") as caught:
        sync_client.wait_for_run("co_1", "run_1", timeout=0.5, poll_interval=0.01)
    assert (caught.value.status, caught.value.request_id) == (200, "req_mock")
    assert len(server.requests) == 1
    batch = {key: value for key, value in fixture("getCompanyBatch").items() if key != "running"}
    server.add("GET", COMPANY + "/batch/b_1", Reply(json=batch))
    with pytest.raises(tungoai.DecodeError, match="running"):
        sync_client.wait_for_batch("co_1", "b_1", timeout=0.5, poll_interval=0.01)


def test_run_scenario_and_wait(sync_client: Tungo, server: MockServer) -> None:
    started = {
        **fixture("runCompanyAutomationsScenario"),
        "id": "run_1",
        "state": "queued",
    }
    server.add(
        "POST",
        COMPANY + "/automations/scenarios/sc_1/run",
        Reply(status=202, json=started),
    )
    server.add(
        "GET",
        COMPANY + "/automations/runs/run_1",
        Reply(json=run_body("running")),
        Reply(json=run_body("done")),
    )
    run = sync_client.run_scenario_and_wait("co_1", "sc_1", event_id="evt_1", poll_interval=0.01)
    assert (run.id, run.state) == ("run_1", "done")
    assert server.requests[0].json() == {"event_id": "evt_1"}
    assert [request.method for request in server.requests] == ["POST", "GET", "GET"]


def test_wait_for_batch(sync_client: Tungo, server: MockServer) -> None:
    running = {**fixture("getCompanyBatch"), "id": "b_1", "running": True}
    server.add(
        "GET",
        COMPANY + "/batch/b_1",
        Reply(json=running),
        Reply(json={**running, "running": False}),
    )
    job = sync_client.wait_for_batch("co_1", "b_1", poll_interval=0.01)
    assert job.running is False
    assert len(server.requests) == 2
    server.add("GET", COMPANY + "/batch/b_1", Reply(json=running))
    with pytest.raises(tungoai.WaitTimeoutError):
        sync_client.wait_for_batch("co_1", "b_1", timeout=0.2, poll_interval=0.05)


def test_verify_webhook_uses_the_secret_of_the_client() -> None:
    secret = "whsec_" + base64.b64encode(b"0123456789abcdef").decode()
    body = b'{"id":"evt_1","type":"brand.new_event","created_at":"2026-11-09T15:00:00Z","data":{"x":1}}'
    stamp = str(int(time.time()))
    digest = hmac.new(b"0123456789abcdef", b"msg_1." + stamp.encode() + b"." + body, hashlib.sha256).digest()
    headers = {
        "Webhook-Id": "msg_1",
        "Webhook-Timestamp": stamp,
        "Webhook-Signature": "v1," + base64.b64encode(digest).decode(),
    }
    client = Tungo(api_key=API_KEY, webhook_secret=secret)
    event = client.verify_webhook(body, headers)
    assert isinstance(event, tungoai.UnknownVariant), "an event type added later is still delivered"
    assert event.to_dict()["data"] == {"x": 1}
    with pytest.raises(tungoai.WebhookVerificationError) as caught:
        client.verify_webhook(body + b" ", headers)
    assert caught.value.reason == "signature_mismatch"
    with pytest.raises(tungoai.ConfigError):
        Tungo(api_key=API_KEY).verify_webhook(body, headers)
